<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>BizzSmart Admin — Assistant conversations</title><style>:root{--navy:#08142f;--blue:#586ff2;--muted:#768196;--line:#e8ebf2}*{box-sizing:border-box}body{margin:0;background:#f6f8fc;color:#17213b;font-family:Arial,sans-serif}.top{background:var(--navy);color:#fff;padding:19px 0}.wrap{width:min(1120px,calc(100% - 36px));margin:auto}.top-in{display:flex;align-items:center;justify-content:space-between}.brand{font-size:20px;font-weight:800}.brand span{color:#6c80ff}.top small{color:#aab6ce;font-size:11px}.actions{display:flex;gap:8px;align-items:center}.back,.logout{border:1px solid #44537a;background:transparent;color:#fff;border-radius:7px;padding:8px 12px;font-size:11px;text-decoration:none;cursor:pointer}.hero{padding:38px 0 25px;display:flex;justify-content:space-between;align-items:end}.eyebrow{color:#6475ed;letter-spacing:2px;font-size:10px;font-weight:700}.hero h1{margin:8px 0 0;font-size:30px}.stat{background:#fff;border:1px solid var(--line);border-radius:10px;padding:15px 22px;min-width:115px}.stat small{display:block;color:var(--muted);font-size:10px}.stat strong{font-size:23px;display:block;margin-top:4px}.conversation{background:#fff;border:1px solid var(--line);border-radius:10px;margin-bottom:16px;overflow:hidden}.conversation-head{display:flex;justify-content:space-between;gap:16px;padding:16px 18px;background:#fafbfe;border-bottom:1px solid var(--line)}.person b{font-size:14px}.person small{display:block;color:var(--muted);font-size:11px;margin-top:4px}.meta{text-align:right;color:var(--muted);font-size:10px}.messages{padding:14px 18px}.message{border-left:3px solid #dfe4f2;padding:8px 12px;margin:8px 0;color:#3d4a62;font-size:12px;line-height:1.55;white-space:pre-wrap}.message.user{border-color:#687cf1}.message.assistant{border-color:#39b997;background:#f6fbf9}.message small{display:block;color:#929bad;font-size:9px;margin-bottom:3px;text-transform:uppercase;letter-spacing:.5px}.empty{text-align:center;color:var(--muted);padding:55px;background:#fff;border:1px solid var(--line);border-radius:10px}.pagination{padding:15px}.pagination nav{display:flex;justify-content:center}.pagination svg{width:18px}.pagination a,.pagination span{margin:0 3px;padding:6px 9px;border:1px solid var(--line);border-radius:5px;font-size:11px;text-decoration:none;color:#5363db}.pagination span[aria-current]{background:var(--blue);color:#fff}@media(max-width:650px){.hero{display:block}.stat{margin-top:18px;width:max-content}.conversation-head{display:block}.meta{text-align:left;margin-top:12px}}</style></head><body><header class="top"><div class="wrap top-in"><div><div class="brand">Bizz<span>Smart</span></div><small>Admin console</small></div><div class="actions"><a class="back" href="{{ route('admin.dashboard') }}">Demo requests</a><form method="POST" action="{{ route('admin.logout') }}">@csrf<button class="logout" type="submit">Sign out</button></form></div></div></header><main class="wrap"><section class="hero"><div><div class="eyebrow">PRODUCT ASSISTANT</div><h1>Conversation history</h1></div><div class="stat"><small>Total conversations</small><strong>{{ $totalConversations }}</strong></div></section>@forelse($conversations as $conversation)<article class="conversation"><div class="conversation-head"><div class="person"><b>{{ $conversation->name }}</b><small>{{ $conversation->email }} · {{ $conversation->phone }}{{ $conversation->company ? ' · '.$conversation->company : '' }}</small></div><div class="meta">Started {{ $conversation->created_at->format('d M Y, h:i A') }}<br>Last message {{ optional($conversation->last_message_at)->format('d M Y, h:i A') }}</div></div><div class="messages">@foreach($conversation->messages as $message)<div class="message {{ $message->role }}"><small>{{ $message->role }}</small>{{ $message->content }}</div>@endforeach</div></article>@empty<div class="empty">No assistant conversations yet.</div>@endforelse<div class="pagination">{{ $conversations->links() }}</div></main></body></html>
